const input = $('When Executed by Another Workflow').first()?.json || {};
let facts = Array.isArray(input.facts_extracted) ? input.facts_extracted : [];
if (typeof input.facts_extracted === 'string') {
  try { facts = JSON.parse(input.facts_extracted); } catch (e) { facts = []; }
}
const conversationId = input.conversation_id || '';
const contactId = input.contact_id || '';
const leadStage = input.lead_stage || 'new';
const intent = input.intent || 'general_inquiry';
const escalate = !!input.escalate;
const escalationReason = input.escalation_reason || '';

return [{
  json: {
    conversation_id: conversationId,
    contact_id: contactId,
    lead_stage: leadStage,
    intent,
    sentiment: input.sentiment || 'neutral',
    escalate,
    escalation_reason: escalationReason,
    facts_extracted: facts,
    customer_name: input.customer_name || '',
    phone: input.phone || '',
  }
}];

const item = $input.first()?.json || {};
const facts = Array.isArray(item.facts_extracted) ? item.facts_extracted : [];
const contactId = item.contact_id || '';
const conversationId = item.conversation_id || '';
const leadStage = item.lead_stage || 'new';
const intent = item.intent || 'general_inquiry';
const sentiment = item.sentiment || 'neutral';
const escalate = !!item.escalate;
const escalationReason = item.escalation_reason || '';

const results = [];
for (const fact of facts) {
  if (fact && fact.key && fact.value) {
    results.push({
      contact_id: contactId,
      conversation_id: conversationId,
      fact_key: String(fact.key),
      fact_value: String(fact.value),
      confidence: typeof fact.confidence === 'number' ? fact.confidence : 1.0,
      source: 'ai',
      lead_stage: leadStage,
      intent,
      sentiment,
      escalate,
      escalation_reason: escalationReason,
    });
  }
}

if (results.length === 0) {
  results.push({
    contact_id: contactId,
    conversation_id: conversationId,
    fact_key: null,
    fact_value: null,
    confidence: 0,
    source: 'ai',
    lead_stage: leadStage,
    intent,
    sentiment,
    escalate,
    escalation_reason: escalationReason,
  });
}

return results.map(r => ({ json: r }));

const trigger = $('When Executed by Another Workflow').first()?.json || {};
let stageUpdate = {};
try { stageUpdate = $('Update Conversation Stage').first()?.json || {}; } catch (e) {}
let handoff = {};
try { handoff = $('Call Handoff Tool').first()?.json || {}; } catch (e) {}

return [{
  json: {
    success: true,
    conversation_id: trigger.conversation_id,
    contact_id: trigger.contact_id,
    lead_stage: trigger.lead_stage,
    intent: trigger.intent,
    sentiment: trigger.sentiment,
    escalate: !!trigger.escalate,
    conversation_stage_updated: !!stageUpdate.id,
    handoff_triggered: !!handoff.success,
    handoff_reason: handoff.success ? trigger.escalation_reason : null,
  }
}];
